-- RTS Panel By Bene - Migrasi Produksi
-- Jalankan pada benedics_benes_sales setelah backup.
-- File aman diulang karena memakai IF NOT EXISTS.

ALTER TABLE `master_toko` ADD COLUMN IF NOT EXISTS `tipe_customer` ENUM('REGULER','GSP') NOT NULL DEFAULT 'REGULER' AFTER `id_customer`;
ALTER TABLE `sales_users` ADD COLUMN IF NOT EXISTS `username` VARCHAR(50) DEFAULT NULL AFTER `email`, ADD COLUMN IF NOT EXISTS `salesman` VARCHAR(150) DEFAULT NULL AFTER `role`, ADD COLUMN IF NOT EXISTS `sales_district` VARCHAR(100) DEFAULT NULL AFTER `salesman`, ADD COLUMN IF NOT EXISTS `status_aktif` ENUM('Aktif','Nonaktif') NOT NULL DEFAULT 'Aktif' AFTER `sales_district`;
ALTER TABLE `pengajuan_gsp` ADD COLUMN IF NOT EXISTS `jenis_request` ENUM('PENAMBAHAN','PENGHAPUSAN') NOT NULL DEFAULT 'PENAMBAHAN' AFTER `id`, ADD COLUMN IF NOT EXISTS `processed_by` VARCHAR(150) DEFAULT NULL, ADD COLUMN IF NOT EXISTS `processed_at` TIMESTAMP NULL DEFAULT NULL, ADD COLUMN IF NOT EXISTS `approval_note` TEXT DEFAULT NULL;
ALTER TABLE `pengajuan_sales` ADD COLUMN IF NOT EXISTS `processed_by` VARCHAR(150) DEFAULT NULL, ADD COLUMN IF NOT EXISTS `processed_at` TIMESTAMP NULL DEFAULT NULL, ADD COLUMN IF NOT EXISTS `approval_note` TEXT DEFAULT NULL;
CREATE TABLE IF NOT EXISTS `master_toko_deleted` (`id` INT NOT NULL AUTO_INCREMENT,`original_id` INT DEFAULT NULL,`id_customer` VARCHAR(50) DEFAULT NULL,`nama_toko` VARCHAR(150) DEFAULT NULL,`tipe_customer` ENUM('REGULER','GSP') NOT NULL DEFAULT 'REGULER',`salesman` VARCHAR(150) DEFAULT NULL,`alamat` TEXT DEFAULT NULL,`kunjungan` VARCHAR(50) DEFAULT NULL,`hari` VARCHAR(20) DEFAULT NULL,`sales_district` VARCHAR(100) DEFAULT NULL,`longitude` VARCHAR(50) DEFAULT NULL,`latitude` VARCHAR(50) DEFAULT NULL,`status_aktif` VARCHAR(20) DEFAULT NULL,`alasan_penghapusan` TEXT DEFAULT NULL,`dihapus_oleh` VARCHAR(150) DEFAULT NULL,`dihapus_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `notifications` (`id` INT NOT NULL AUTO_INCREMENT,`user_id` INT DEFAULT NULL,`recipient_email` VARCHAR(100) DEFAULT NULL,`title` VARCHAR(150) NOT NULL,`message` TEXT NOT NULL,`type` ENUM('INFO','SUCCESS','WARNING','DANGER') NOT NULL DEFAULT 'INFO',`reference_type` VARCHAR(50) DEFAULT NULL,`reference_id` INT DEFAULT NULL,`is_read` TINYINT(1) NOT NULL DEFAULT 0,`created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `api_tokens` (`id` INT NOT NULL AUTO_INCREMENT,`user_id` INT NOT NULL,`token_hash` CHAR(64) NOT NULL,`device_name` VARCHAR(100) DEFAULT NULL,`expires_at` TIMESTAMP NOT NULL,`last_used_at` TIMESTAMP NULL DEFAULT NULL,`created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `uq_api_token_hash` (`token_hash`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
UPDATE `master_toko` SET `tipe_customer`='REGULER' WHERE `tipe_customer` IS NULL OR `tipe_customer`='';
